from astropy.io import fitsimport numpy as npimport matplotlib.pyplot as pltimport glob# folder with HIRES filesfolder = "data/koa/HIRES/KELT-1/lev1/extracted/HI.20170702.51878"files = sorted(glob.glob(f"{folder}/*.fits.gz"))# Hα rest wavelengthhalpha_rest = 6562.8# region around Hαregion_min = 6548region_max = 6575# broader EW region ew_min = 6560.3ew_max = 6565.8found = Falsefor file in files:    print(f"\nTrying: {file}")    try:        with fits.open(file) as hdul:            # skip bad files            if len(hdul) < 2 or hdul[1].data is None:                continue            table = hdul[1].data            # get wavelength and flux            try:                wave = np.ravel(table['WAVE'])                flux = np.ravel(table['FLUX'])            except KeyError:                continue        # remove bad values        mask = np.isfinite(wave) & np.isfinite(flux)        wave = wave[mask]        flux = flux[mask]        if len(wave) == 0:            continue        # sort        idx = np.argsort(wave)        wave = wave[idx]        flux = flux[idx]        print(f"  -> Range: {wave.min():.1f} to {wave.max():.1f} Å")        # check if Hα is present        if not np.any((wave > 6560) & (wave < 6565)):            continue        print("  -> Hα found!")        # isolate region        mask_ha = (wave >= region_min) & (wave <= region_max)        wave_ha = wave[mask_ha]        flux_ha = flux[mask_ha]        if len(wave_ha) < 10:            continue        # smooth to find center        flux_smooth = np.convolve(flux_ha, np.ones(5)/5, mode="same")        i_min = np.argmin(flux_smooth)        halpha_obs = wave_ha[i_min]        delta_lambda = halpha_obs - halpha_rest        print(f"  -> Observed center: {halpha_obs:.3f} Å")        print(f"  -> Shift: {delta_lambda:.3f} Å")        # shift to rest frame        wave_rest = wave - delta_lambda        # cut region again        mask_rest = (wave_rest >= region_min) & (wave_rest <= region_max)        wave_rest = wave_rest[mask_rest]        flux_rest = flux[mask_rest]        if len(wave_rest) < 10:            continue        # sort again        idx = np.argsort(wave_rest)        wave_rest = wave_rest[idx]        flux_rest = flux_rest[idx]        #  BETTER continuum regions (farther from line)        continuum_mask = ((wave_rest > 6549.0) & (wave_rest < 6554.0)) | \                         ((wave_rest > 6568.0) & (wave_rest < 6573.0))        if len(wave_rest[continuum_mask]) < 5:            print("  -> Not enough continuum")            continue        # normalize continuum points first (robust step)        cont_flux = flux_rest[continuum_mask]        cont_wave = wave_rest[continuum_mask]        # remove outliers (important)        median = np.median(cont_flux)        std = np.std(cont_flux)        good = np.abs(cont_flux - median) < 2*std        cont_wave = cont_wave[good]        cont_flux = cont_flux[good]        # now fit clean data        coeffs = np.polyfit(cont_wave, cont_flux, 1)        continuum = np.polyval(coeffs, wave_rest)        flux_norm = flux_rest / continuum                     # EW region        ew_mask = (wave_rest >= ew_min) & (wave_rest <= ew_max)        wave_ew = wave_rest[ew_mask]        flux_ew = flux_norm[ew_mask]        if len(wave_ew) < 2:            print("  -> Not enough points for EW")            continue        # compute EW        ew = np.trapz(1 - flux_ew, wave_ew)        print(f"\nHα Equivalent Width = {ew:.4f} Å")        # plot        plt.figure(figsize=(8,5))        plt.plot(wave_rest, flux_norm, label="Normalized Spectrum")        plt.axvline(halpha_rest, color="red", linestyle="--", label="Hα 6562.8 Å")        plt.fill_between(wave_ew, flux_ew, 1, alpha=0.3, label="EW region")        plt.xlabel("Wavelength (Å)")        plt.ylabel("Normalized Flux")        plt.title(f"Hα Equivalent Width\n{file.split('/')[-1]}")        plt.legend()        plt.tight_layout()        plt.show()        found = True        break    except Exception as e:        print(f"  -> Error: {e}")if not found:    print("\nNo file with usable Hα data found.")